import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as o,c as l,o as e,af as r,b as h,w as a,a as i,G as s,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const B=JSON.parse('{"title":"模型架构（桥接）","description":"Transformer / Attention / RoPE / MoE / KV cache 的一句话定位表——应用工程师不必会推导，但必须能把架构术语翻译成 context 长度、推理成本与多模态路径上的工程变量；推导归 Learn LLM。","frontmatter":{"title":"模型架构（桥接）","description":"Transformer / Attention / RoPE / MoE / KV cache 的一句话定位表——应用工程师不必会推导，但必须能把架构术语翻译成 context 长度、推理成本与多模态路径上的工程变量；推导归 Learn LLM。","domain":"tech","tags":["tech","model-lifecycle","bridge","architecture"],"navOrder":12,"topicId":"architecture","layer":"1","status":"bridge","nodeType":"concept","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/07-attention"}],"prerequisites":["llm-mental-model"],"next":["data-pretraining-scaling"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/architecture.md","filePath":"zh/tech/01-model-lifecycle/architecture.md","lastUpdated":1791173509000}'),p={name:"zh/tech/01-model-lifecycle/architecture.md"};function E(f,t,m,A,b,L){const d=o("Mermaid");return e(),l("div",null,[t[1]||(t[1]=r('<blockquote><p><strong>在哪一组</strong>：组 01 · 模型生命周期（桥接组）｜ <strong>上一组出口</strong>：能判断知识归属、并为需求选出最低复杂度方案（00-map 组） ｜ <strong>本页出口</strong>：能把厂商发布里的架构术语（长上下文、MoE、缓存定价）翻译成 context 长度、推理成本与输入形态上的工程变量 <strong>前置</strong>：<a href="./llm-mental-model.html">LLM 心智模型（桥接）</a> ｜ <strong>下一步</strong>：<a href="./data-pretraining-scaling.html">数据、预训练与 Scaling（桥接）</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：应用工程师不需要会推导 Attention，但必须有<strong>位置感</strong>——架构在预训练时冻结，直接决定 context 长度、推理成本与多模态路径，这三样都出现在你的 API 账单和选型表里。本页给每个构件「是什么 / 影响你什么决策」的一句话定位；推导与手写实现归 Learn LLM 第 7、9、20 章。</p><h3 id="一句话定位表" tabindex="-1">一句话定位表 <a class="header-anchor" href="#一句话定位表" aria-label="Permalink to &quot;一句话定位表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>构件</th><th>是什么（一句话）</th><th>影响你什么决策</th></tr></thead><tbody><tr><td>Transformer</td><td>基于 self-attention 的序列骨架，现代 LLM 的公共底座</td><td>换模型 = 换一组权重、接口不变；迁移成本远低于换范式</td></tr><tr><td>Attention</td><td>序列内 token 两两加权的关注机制；causal mask 保证逐 token 生成</td><td>注意力计算随序列长度增长——长上下文更贵的原因</td></tr><tr><td>位置编码（RoPE）</td><td>把位置信息旋转进 query/key，让模型感知 token 顺序</td><td>模型标称 context 长度的来源；窗口扩展是版本升级的常变量</td></tr><tr><td>MoE（混合专家）</td><td>每层只激活部分专家参数：总参数大、单 token 激活小</td><td>参数量与每 token 成本脱钩；厂商定价差异的架构根源</td></tr><tr><td>KV cache 与 MQA / GQA</td><td>推理期缓存注意力的键值，及其体积压缩变体</td><td>prefill / decode 成本结构与 prompt 前缀缓存定价</td></tr></tbody></table><h3 id="为什么是位置感而不是推导能力" tabindex="-1">为什么是位置感而不是推导能力 <a class="header-anchor" href="#为什么是位置感而不是推导能力" aria-label="Permalink to &quot;为什么是位置感而不是推导能力&quot;">​</a></h3>',6)),(e(),h(c,null,{default:a(()=>[s(d,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20S%20%5B%22%E6%9E%B6%E6%9E%84%E6%9E%84%E4%BB%B6%EF%BC%88%E9%A2%84%E8%AE%AD%E7%BB%83%E6%97%B6%E5%86%BB%E7%BB%93%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22Attention%20%2F%20%E4%BD%8D%E7%BD%AE%E7%BC%96%E7%A0%81%22%5D%0A%20%20%20%20%20%20%20%20A2%5B%22MoE%20%2F%20KV%20cache%20%E5%8F%98%E4%BD%93%22%5D%0A%20%20%20%20%20%20%20%20A3%5B%22%E5%A4%9A%E6%A8%A1%E6%80%81%E6%8A%95%E5%BD%B1%E5%B1%82%22%5D%0A%20%20%20%20end%0A%20%20%20%20A1%20--%3E%20P1%5B%22context%20%E9%95%BF%E5%BA%A6%22%5D%0A%20%20%20%20A2%20--%3E%20P2%5B%22%E6%8E%A8%E7%90%86%E6%88%90%E6%9C%AC%22%5D%0A%20%20%20%20A3%20--%3E%20P3%5B%22%E5%8F%AF%E7%94%A8%E7%9A%84%E8%BE%93%E5%85%A5%E5%BD%A2%E6%80%81%22%5D%0A%20%20%20%20P1%20--%3E%20O%5B%22%E4%BD%A0%E5%9C%A8%20API%20%E4%B8%8A%E7%9C%8B%E5%88%B0%E7%9A%84%E6%8E%A5%E5%8F%A3%E5%B1%9E%E6%80%A7%22%5D%0A%20%20%20%20P2%20--%3E%20O%0A%20%20%20%20P3%20--%3E%20O%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<p>架构是左链把物理约束冻结成接口属性的位置：训练结束后，谁也不能改这个模型的窗口假设或专家路由，只能等厂商发新版本。因此架构知识的工程形态是「读 release note 与定价页时的解码能力」，不是可写能力。厂商发布会上的「更长上下文」「更便宜档位」几乎都是架构变量——但落地约束以厂商文档为准。</p><h2 id="_2-何时跳转" tabindex="-1">2. 何时跳转 <a class="header-anchor" href="#_2-何时跳转" aria-label="Permalink to &quot;2. 何时跳转&quot;">​</a></h2><p>本页无可运行产物；按下表路由：</p><table tabindex="0"><thead><tr><th>症状 / 问题</th><th>该读哪</th><th>为什么</th></tr></thead><tbody><tr><td>想看 Attention 手写实现、causal mask 为什么存在</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/07-attention" target="_blank" rel="noreferrer">第 7 章</a></td><td>Transformer 从零实现的 canonical</td></tr><tr><td>KV cache、量化、prefill / decode 成本模型</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/09-inference-cache" target="_blank" rel="noreferrer">第 9 章</a></td><td>推理优化的工程细节</td></tr><tr><td>MLA / MoE 记账 / 现代架构专题</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/20-deepseek" target="_blank" rel="noreferrer">第 20 章</a></td><td>DeepSeek 系架构专题</td></tr><tr><td>API 计费、前缀缓存折扣怎么用</td><td>本仓 <a href="./../02-inference-interface/model-api.html">Model API 契约</a></td><td>应用侧消费方式归本仓</td></tr><tr><td>长会话该塞多少上下文</td><td>本仓 <a href="./../03-context/">03-context 组</a></td><td>上下文取舍是本仓主线</td></tr><tr><td>厂商新架构版本对线上的影响</td><td>本仓 <a href="./../08-production/">08-production 组</a></td><td>版本升级回归是运维问题</td></tr></tbody></table><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>一段定位：Transformer 用 self-attention 替代循环结构获得训练并行性，代价是注意力计算随长度增长；RoPE 决定模型能外推到多长的上下文；MoE 用稀疏激活把「总参数」与「单次计算」解耦；KV cache 把 decode 从重算变成查表。这四句话就是应用工程师需要的全部架构原理——scaled dot-product 为什么除以 √d、RoPE 的复数形式、专家路由的负载均衡，Learn LLM 第 7、9、20 章逐步推导（retrievedAt 2026-09-01），本仓不复制。</p><h2 id="_4-工程决策影响" tabindex="-1">4. 工程决策影响 <a class="header-anchor" href="#_4-工程决策影响" aria-label="Permalink to &quot;4. 工程决策影响&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工程决策</th><th>架构事实</th><th>工程动作</th></tr></thead><tbody><tr><td>长会话成本估算</td><td>注意力与 KV cache 体积随长度增长</td><td>长历史做摘要与裁剪；关注厂商前缀缓存定价</td></tr><tr><td>模型家族选型</td><td>dense 与 MoE 的成本结构不同</td><td>按任务分级，对比每任务实际成本而非参数量</td></tr><tr><td>上下文窗口升级</td><td>窗口扩展常伴随行为变化</td><td>升级后先跑回归评估再切换</td></tr><tr><td>多模态接入</td><td>图像经投影层进 token 空间、按 token 计费</td><td>预算按 token 折算，不等同像素或分辨率</td></tr><tr><td>本地 / 边缘部署</td><td>量化变体改变精度-成本平衡</td><td>数学归 Learn LLM 第 9 章；选型决策走本仓 02-inference-interface 组</td></tr></tbody></table><p>维护规则（替代 runbook）：Learn LLM 第 7/9/20 章结构调整时重验本页 deep-link 并更新 <code>lastVerified</code>；本页不维护各厂商的架构采用清单——那会随版本漂移，以各厂商模型文档为准。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><table tabindex="0"><thead><tr><th>级</th><th>读什么</th><th>为什么是这个顺序</th></tr></thead><tbody><tr><td>Beginner</td><td>本页定位表 + <a href="./index.html">组导览</a></td><td>先建立「构件 → 接口属性」的映射</td></tr><tr><td>Builder</td><td>本仓 <a href="./../02-inference-interface/model-api.html">Model API 契约</a></td><td>在接口层消费这些架构属性</td></tr><tr><td>Operator</td><td><a href="./../08-production/cost-performance.html">成本与性能</a></td><td>把架构变量纳入成本治理</td></tr><tr><td>Researcher</td><td>Learn LLM 第 7、9、20 章 + 三篇原始论文</td><td>下沉到机制与推导</td></tr></tbody></table><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>层级</th><th>canonical URL</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>Learn LLM 第 7 章 · Transformer</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/07-attention" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/07-attention</a></td><td>Attention / causal mask / 多头的从零实现</td><td>手写 Transformer Block</td></tr><tr><td>Learn LLM 第 9 章 · 推理与量化</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/09-inference-cache" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/09-inference-cache</a></td><td>RoPE、KV cache、MQA/GQA、量化的工程细节</td><td>理解推理成本结构</td></tr><tr><td>Learn LLM 第 20 章 · DeepSeek 专题</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/20-deepseek" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/20-deepseek</a></td><td>MLA / MoE 记账与现代架构演进</td><td>扩展专题选读</td></tr><tr><td>Attention Is All You Need（Vaswani et al., 2017）</td><td>L4</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">https://arxiv.org/abs/1706.03762</a></td><td>Transformer 架构的原始论文</td><td>读 attention 一节</td></tr><tr><td>RoFormer（Su et al., 2021）</td><td>L4</td><td><a href="https://arxiv.org/abs/2104.09864" target="_blank" rel="noreferrer">https://arxiv.org/abs/2104.09864</a></td><td>RoPE 位置编码的提出</td><td>读旋转位置编码一节</td></tr><tr><td>Switch Transformers（Fedus et al., 2021）</td><td>L4</td><td><a href="https://arxiv.org/abs/2101.03961" target="_blank" rel="noreferrer">https://arxiv.org/abs/2101.03961</a></td><td>稀疏 MoE 的代表工作</td><td>读专家路由一节</td></tr></tbody></table><p>（Learn LLM 章节经其章节目录核验、arXiv 链接为稳定 abs 地址，retrievedAt 均为 2026-09-01。）</p><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：如果你发现某决策必须依赖架构推导才能做对（如自实现注意力内核），它属于 Learn LLM 或推理引擎团队，不是本页——请下沉断言，不要在此扩写。</li><li>未决：各厂商对 MQA / GQA / MLA 与长上下文外推的采用情况随版本快速漂移，本页不维护采用清单；使用时以各厂商模型卡与定价页为准。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>Attention、RoPE、MoE 的机制与推导：Learn LLM 第 7、9、20 章——本仓到此为止。</li><li>在接口层消费架构属性：本仓 <a href="./../02-inference-interface/">02-inference-interface 组</a>。</li><li>组内下一页：<a href="./data-pretraining-scaling.html">数据、预训练与 Scaling（桥接）</a>。</li></ul>',19))])}const M=n(p,[["render",E]]);export{B as __pageData,M as default};
